import { Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

// Define available icons in the system
export type IconName = 
  'arrow-down' | 
  'arrow-up' | 
  'check' | 
  'close' | 
  'info' | 
  'warning' | 
  'success' | 
  'error' | 
  'user' | 
  'settings';

export type IconSize = 'sm' | 'md' | 'lg';

@Component({
  selector: 'app-icon',
  standalone: true,
  imports: [CommonModule],
  template: `
    <span 
      class="icon"
      [ngClass]="['icon--' + size]"
      [innerHTML]="svgContent"
      [style.color]="color"
      aria-hidden="true"
    ></span>
  `,
  styleUrls: ['./icon.component.scss']
})
export class IconComponent implements OnChanges {
  @Input() name!: IconName;
  @Input() size: IconSize = 'md';
  @Input() color?: string;

  svgContent: SafeHtml = '';

  constructor(private sanitizer: DomSanitizer) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['name']) {
      this.updateIcon();
    }
  }

  private updateIcon(): void {
    const icon = this.getIconSvg(this.name);
    this.svgContent = this.sanitizer.bypassSecurityTrustHtml(icon);
  }

  private getIconSvg(name: IconName): string {
    const icons: Record<IconName, string> = {
      'arrow-down': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M5 12l7 7 7-7"/></svg>',
      'arrow-up': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 19V5M5 12l7-7 7 7"/></svg>',
      'check': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>',
